        byte[] orig = new byte[i];
        for (byte j = 0; j < i; j++) {
            orig[j] = j;
        }
        byte[] cipherText = Crypto.aes128cbcEncrypt(key, orig);
        byte[] plainText = Crypto.aes128cbcDecrypt(key, cipherText);
        assertArrayEquals("Array of length " + i, orig, plainText);
    }
}

