    FakeHttpServletRequest request = new FakeHttpServletRequest();
    request.setMethod("GET");
    assertFalse(multipartFormParser.isMultipartContent(request));
    request.setMethod("POST");
    assertFalse(multipartFormParser.isMultipartContent(request));
