    replay(visitor);
    MutableContent mc = getContent(0);
    DomWalker.Rewriter rewriter = getRewriter(visitor);
    rewriter.rewrite(gadget, mc);
    // Verifying mutations on MutableContent completes the test.
    verify(mc);
}

